using System;
using System.Collections.Generic;
using System.Linq;
using AutoMapSharp;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace AutoMapSharp.IntegrationTests.NugetConsumer;

/// <summary>
/// Verifies the remediation Phase 10 hotfixes through the packed NuGet package,
/// including real SQL generated by EF Core for parameterized projections.
/// </summary>
public class RemediationPhase10ConsumerTests
{
    public class Shipment
    {
        public int Id { get; set; }
        public int? Priority { get; set; }
        public DateTime? DeliveredAt { get; set; }
        public TimeSpan TransitTime { get; set; }
        public object? Tag { get; set; }
        public List<Parcel> Parcels { get; set; } = new();
    }

    public class Parcel
    {
        public int Id { get; set; }
        public int OwnerId { get; set; }
        public int ShipmentId { get; set; }
    }

    public class ShipmentDto
    {
        public int Id { get; set; }
        public int? Priority { get; set; }
        public DateTime? DeliveredAt { get; set; }
        public TimeSpan TransitTime { get; set; }
        public object? Tag { get; set; }
        public string? Type { get; set; }
    }

    public class ShipmentCountDto
    {
        public int Id { get; set; }
        public int OwnedParcels { get; set; }
    }

    public class ShipmentModule : MappingModule
    {
        public ShipmentModule()
        {
            // ShipmentDto.Type has no source member on purpose: it proves GetType() is not used as a source.
            // The AMS001 analyzer correctly reports it, so the warning is suppressed for this one map.
#pragma warning disable AMS001
            DefineMap<Shipment, ShipmentDto>();
#pragma warning restore AMS001

            int ownerId = 0;
            DefineMap<Shipment, ShipmentCountDto>()
                .ForProperty(d => d.OwnedParcels, o => o.MapSource(s => s.Parcels.Count(p => p.OwnerId == ownerId)));
        }
    }

    public class ShipmentDbContext : DbContext
    {
        public ShipmentDbContext(DbContextOptions<ShipmentDbContext> options) : base(options) { }

        public DbSet<Shipment> Shipments => Set<Shipment>();

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<Shipment>().Ignore(s => s.Tag);
        }
    }

    [Fact]
    public void Package_PreservesNullableStructAndObjectValues()
    {
        var engine = new MapEngine(new ShipmentModule());
        var tag = new { Code = "X1" };
        var source = new Shipment
        {
            Id = 1,
            Priority = 3,
            DeliveredAt = new DateTime(2026, 11, 7, 9, 30, 0),
            TransitTime = TimeSpan.FromHours(36),
            Tag = tag
        };

        var result = engine.Map<Shipment, ShipmentDto>(source);

        Assert.Equal(3, result.Priority);
        Assert.Equal(source.DeliveredAt, result.DeliveredAt);
        Assert.Equal(TimeSpan.FromHours(36), result.TransitTime);
        Assert.Same(tag, result.Tag);
        Assert.Null(result.Type);
    }

    [Fact]
    public void Package_ParameterizedProjection_UsesSqlParameterAndCorrectValuePerCall()
    {
        using var connection = new SqliteConnection("DataSource=:memory:");
        connection.Open();
        var options = new DbContextOptionsBuilder<ShipmentDbContext>().UseSqlite(connection).Options;

        using (var setup = new ShipmentDbContext(options))
        {
            setup.Database.EnsureCreated();
            setup.Shipments.Add(new Shipment
            {
                Id = 1,
                Parcels = new()
                {
                    new() { Id = 1, OwnerId = 5 },
                    new() { Id = 2, OwnerId = 7 },
                    new() { Id = 3, OwnerId = 7 }
                }
            });
            setup.SaveChanges();
        }

        var engine = new MapEngine(new ShipmentModule());
        using var db = new ShipmentDbContext(options);

        var forOwner5 = db.Shipments.ProjectOnto<ShipmentCountDto>(engine, new { ownerId = 5 });
        var forOwner7 = db.Shipments.ProjectOnto<ShipmentCountDto>(engine, new { ownerId = 7 });

        Assert.Equal(1, forOwner5.Single().OwnedParcels);
        Assert.Equal(2, forOwner7.Single().OwnedParcels);

        var sql = forOwner7.ToQueryString();
        var selectStatement = sql.Substring(sql.IndexOf("SELECT", StringComparison.Ordinal));
        Assert.Contains("\"OwnerId\" = @", selectStatement);
        Assert.DoesNotContain("= 7", selectStatement);
    }
}
